#!/usr/bin/env bash
# Controls for witforge-consumer.sh. In a copy of the contract and the
# generated consumer crate, the unmodified copy must pass; a changed, extra, or
# missing generated file must fail naming it; and a contract whose wire lock
# lost an entry must fail `witforge check`.
#
# Needs witforge. Without it this harness skips, unless WITFORGE_REQUIRED=1
# (set by the CI job that installs the pinned release), where it fails.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
WITFORGE_BIN="${WITFORGE_BIN:-witforge}"
if ! "$WITFORGE_BIN" --version >/dev/null 2>&1; then
  if [[ "${WITFORGE_REQUIRED:-}" == 1 ]]; then
    echo "::error title=witforge consumer::witforge is not installed (WITFORGE_BIN=${WITFORGE_BIN})" >&2
    exit 1
  fi
  echo "[witforge-consumer] skipped: witforge is not installed (WITFORGE_REQUIRED=1 makes this fail)"
  exit 0
fi
export WITFORGE_BIN

CRATE="crates/alint-witforge-consumer"
TMP_ROOT=$(mktemp -d)
trap 'rm -rf "$TMP_ROOT"' EXIT

pristine="$TMP_ROOT/pristine"
mkdir -p "$pristine/ci/scripts" "$pristine/crates"
cp "$REPO_ROOT/ci/scripts/witforge-consumer.sh" "$pristine/ci/scripts/"
cp -R "$REPO_ROOT/wit" "$pristine/wit"
cp -R "$REPO_ROOT/$CRATE" "$pristine/$CRATE"

failures=0
fail() {
  echo "FAIL: $*" >&2
  failures=$((failures + 1))
}

# run_check <copy>: sets $rc and $out.
run_check() {
  set +e
  out=$(bash "$1/ci/scripts/witforge-consumer.sh" 2>&1)
  rc=$?
  set -e
}

run_check "$pristine"
if [[ $rc -ne 0 ]]; then
  fail "the unmodified copy fails the check (rc=$rc):"
  printf '%s\n' "$out" >&2
fi

# control <name> <expected output> <shell edit, run inside the copy>
control() {
  local name=$1 expected=$2 edit=$3 copy
  copy="$TMP_ROOT/$name"
  cp -R "$pristine" "$copy"
  (cd "$copy" && eval "$edit")
  run_check "$copy"
  if [[ $rc -eq 0 ]]; then
    fail "$name: the check passed"
  elif ! grep -qF -- "$expected" <<<"$out"; then
    fail "$name: the check failed without \"$expected\" (rc=$rc):"
    printf '%s\n' "$out" >&2
  else
    echo "ok: $name fails the check"
  fi
}

for file in src/plain/v0_1.rs src/glue/mod.rs src/glue/v0.rs proto/v0.proto; do
  control "changed-${file//\//-}" "changed generated file \`$CRATE/$file\`" \
    "echo '// edited by hand' >> '$CRATE/$file'"
done
control extra-file "extra generated file \`$CRATE/src/glue/v1.rs\`" \
  "printf '// @generated by witforge; do not edit.\n' > '$CRATE/src/glue/v1.rs'"
control missing-file "missing generated file \`$CRATE/src/plain/v0_1.rs\`" \
  "rm '$CRATE/src/plain/v0_1.rs'"
# A wire-lock entry removed: the member it numbered is no longer locked.
control unlocked-member "has no wire number" \
  "python3 - wit/alint-plugin/v0.1/wire.lock <<'PY'
import sys
path = sys.argv[1]
lines = open(path).read().splitlines(keepends=True)
entries = [i for i, line in enumerate(lines) if line.strip() and not line.startswith('#')]
del lines[entries[-1]]
open(path, 'w').write(''.join(lines))
PY"

if [[ $failures -ne 0 ]]; then
  echo "[witforge-consumer] $failures control(s) failed" >&2
  exit 1
fi
echo "[witforge-consumer] OK: the unmodified contract passes and every control fails"
